async function respond(action){const identity={...who()},t=current(),s=together();if(!identity.roleId||!t||!s||pending)return;if(action!=='invite'&&!s.active)return;const replaced=action==='reroll'?rerollTarget(s):null;if(action==='reroll'&&!replaced)return;const task=replaced?.musicReplyAction||action,version=epoch,request=++requestSerial,position=audio?.currentTime||0;pending=true;persist();renderPage();
 try{const context=rt.context(identity),requestSession=replaced?{...s,thread:s.thread.filter(m=>m.id!==replaced.id)}:s,prompt=C.prompt(task,context,t,position,requestSession,tracks()),result=C.parse(await rt.request(prompt),task==='invite');if(version!==epoch||!same(identity)||!tracks().includes(t))return;
 delete s.failedRequest;if(task==='invite'){s.active=result.accepted;if(s.active)C.begin(s,t)}const suggestion=result.suggestion&&(result.suggestion.type==='repeat'||(result.suggestion.type==='next'&&C.next(tracks(),trackId,pref().mode))||(result.suggestion.type==='track'&&tracks().some(x=>x.id===result.suggestion.trackId)))?{...result.suggestion,fromTrackId:t.id,resolved:false}:null;
 if(replaced){const index=s.thread.findIndex(m=>m.id===replaced.id);if(index<0)return;s.thread.splice(index,1);for(const run of s.runs||[])run.messages=(run.messages||[]).filter(m=>m.id!==replaced.id)}
 C.append(s,{mine:false,text:result.text,trackId:t.id,position,suggestion:task==='invite'?null:suggestion,...(task!=='invite'?{musicReply:true,musicReplyAction:task}:{})});persist();
 }catch(error){if(version===epoch&&same(identity)){s.failedRequest={action,trackId:t.id};persist();fail(error)}}finally{if(request===requestSerial)pending=false;if(visible())renderPage();syncMini()}
}
async function acceptSuggestion(messageId){const s=together(),m=s?.thread.find(x=>x.id===messageId),suggestion=m?.suggestion;if(!s?.active||!suggestion||suggestion.resolved)return;if(suggestion.fromTrackId!==trackId){suggestion.resolved=true;persist();renderPage();return;}suggestion.resolved=true;persist();if(suggestion.type==='repeat'){audio.currentTime=0;await play()}else if(suggestion.type==='next')await step(1);else{const t=tracks().find(x=>x.id===suggestion.trackId);if(t)await load(t,true)}renderPage()}
function endDialog(){const node=openDialog('Together',`<p class="music-end-caption">结束这次一起听</p><div class="music-end-options"><button type="button" data-music-end-keep><span>结束陪伴，继续播放</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10h12m-5-5 5 5-5 5"/></svg></button><button type="button" class="music-action-primary" data-music-end-pause><span>结束并暂停</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M7 5v10M13 5v10"/></svg></button></div>`);for(const [selector,pause]of [['[data-music-end-keep]',false],['[data-music-end-pause]',true]])node.querySelector(selector).onclick=()=>{++epoch;++requestSerial;pending=false;const s=together();if(s)C.end(s);if(pause)audio.pause();savePosition();persist();node.close();renderPage();syncMini()}}
function historyDialog(){const s=together(),i=who();const node=openDialog('Our Music',`<div class="music-history">${s?.runs.length?s.runs.slice().reverse().map(run=>`<article><h3>${esc(run.title)}</h3><small>${esc(new Date(run.startedAt).toLocaleString('zh-CN'))} · ${run.endedAt?'已结束':'正在一起听'}</small><details><summary>查看这次交流</summary>${run.messages.length?run.messages.map(m=>`<p><small>${esc(m.mine?i.userName:i.roleName)}</small>${esc(m.text)}</p>`).join(''):'<p>这次没有留下聊天文字。</p>'}</details><button type="button" data-music-remember="${esc(run.id)}">${run.remembered?'更新共同记忆':'保存为共同记忆'}</button></article>`).join(''):'<p>邀请 TA 一起听后，会在这里留下共同记录。</p>'}</div>`);node.querySelectorAll('[data-music-remember]').forEach(button=>button.onclick=()=>{const run=s.runs.find(x=>x.id===button.dataset.musicRemember);if(!run)return;try{rt.remember({...i},run);run.remembered=true;persist();button.textContent='更新共同记忆'}catch(error){fail(error)}})}
function sync(){if(!rt)return;resolveRoleInvites();if(!sameScope()){for(const request of lyricsRequests.values())request.abort();if(trackId){++epoch;++requestSerial;pending=false;savePosition();loadedTrackId='';audio?.pause();audio?.removeAttribute('src');audio?.load();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}trackId='';try{if(navigator.mediaSession){navigator.mediaSession.metadata=null;navigator.mediaSession.playbackState='none'}}catch{}}if(mini)mini.hidden=true;return}syncMini()}
function acceptRoleInvite(song){if(!song?.id||!song.playUrl||!rt||!who()?.roleId)return false;savePosition();if(!sameScope()){sync();const identity=who();activeScope=[identity.userId,identity.roleId||''].join(':');boundUserId=identity.userId}const existing=tracks().find(item=>item.platform==='netease'&&item.platformId===String(song.id));const t=existing||C.add(rt.state,owner(),{kind:'url',url:song.playUrl,musicAccessMode:song.musicAccessMode||'',playbackSources:song.playbackSources||[],title:song.name,artist:song.artist,album:song.album,cover:song.cover,lyrics:song.lyrics,lyricsSource:song.lyrics?{name:song.lyricSource||'网易云音乐',url:'https://music.163.com'}:null,duration:song.duration,platform:'netease',platformId:String(song.id)});Object.assign(t,{url:song.playUrl,musicAccessMode:song.musicAccessMode||'',playbackSources:song.playbackSources||[],cover:song.cover||t.cover,lyrics:song.lyrics||t.lyrics});cloudState().songs[String(song.id)]=song;const s=together();s.active=true;if(s.runs.find(run=>run.id===s.currentRunId)?.trackId!==t.id)C.begin(s,t);pref().trackId=t.id;trackId=t.id;tab='player';playerView='record';chatExpanded=false;persist();rt.open();queueMicrotask(()=>{if(!sameScope())return;void load(t,true)});return true}
function configure(runtime){rt=runtime;C.normalize(rt.state);const identity=who();activeScope=[identity?.userId||'',identity?.roleId||''].join(':');boundUserId=identity?.userId||''}
function mount(runtime){const previousScope=activeScope;playerView='record';chatExpanded=false;rt=runtime;C.normalize(rt.state);const i=who();if(!i?.userId){rt.content.innerHTML='<section class="music-empty"><p>请先选择一个用户，再打开一起听。</p></section>';return}activeScope=[i.userId,i.roleId||''].join(':');initAudio();if(previousScope&&previousScope!==activeScope){++epoch;++requestSerial;pending=false;savePosition();loadedTrackId='';audio.pause();audio.removeAttribute('src');audio.load();if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=''}trackId='';if(dialog?.open)dialog.close()}boundUserId=i.userId;if(!tracks().some(x=>x.id===trackId))trackId='';audio.volume=1;tab=tracks().length?'player':'library';renderPage();const saved=tracks().find(x=>x.id===pref().trackId);if(!trackId&&saved)void load(saved);syncMini();persist();void restoreCloud()}
